package com.bank.pipeline;

import java.util.*;
import java.util.logging.*;
import java.util.stream.IntStream;

public class StatefulDemo {
    private static final Logger log = Logger.getLogger("Pipeline");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        List<Integer> data = IntStream.range(0, 1_000_000).boxed().toList();
        PipelineService service = new PipelineService();

        log.info(() -> "stateless parallel sum : " + service.statelessSum(data));
        log.info(() -> "stateful parallel sorted-distinct size: "
            + service.statefulSortedDistinct(data));
    }
}

// ─── Would be in service/PipelineService.java ───
class PipelineService {
    // stateless: filter + reduce → parallelises well
    long statelessSum(List<Integer> data) {
        return data.parallelStream()
            .filter(n -> n % 2 == 0)      // stateless
            .mapToLong(n -> n)            // stateless
            .sum();                        // associative reduce
    }

    // stateful: distinct + sorted → buffering + merge, parallel gains limited
    int statefulSortedDistinct(List<Integer> data) {
        return (int) data.parallelStream()
            .distinct()                    // STATEFUL: global dedupe
            .sorted()                      // STATEFUL: cross-chunk sort + merge
            .count();
    }
}
